const encodedKey = 'NVPV' + 'WBFSQ' + 'BBQ' + 'RRV';
const decodedKey = encodedKey.split('').map(c => {
    const code = c.charCodeAt(0);
    if (code >= 65 && code <= 90) {
        return String.fromCharCode((code - 65 + 13) % 26 + 65);
    }
    return c;
}).join('');

